package net.officefloor.hq.app.person;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.officefloor.hq.app.sheet.SheetService;
import net.officefloor.hq.app.statement.StatementService;
import net.officefloor.hq.app.statement.StatementSummary;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.DeleteMapping;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

/** The people on a sheet. The signed-in user's name travels in the {@code X-User} header. */
@RestController
@RequestMapping("/api/sheets/{sheetId}/people")
@Validated
public class PersonController {

    /** One of a person's holds, from its from-date to its to-date (null: it does not end). */
    public record HoldView(LocalDate from, LocalDate to) {
    }

    /** One of a person's grades, from its from-date (null: from the beginning of time). */
    public record GradeView(String grade, LocalDate from) {
    }

    /**
     * A person as shown, with their grade in force on the sheet's today and every grade with its from-date, with how many statements they have had and the due-total and date of the last one. */
    public record PersonView(Long id, String name, String grade, Integer terms, String contact, long version, int statementCount,
            String statedTotal, LocalDate statementDate, boolean retired, LocalDate retiredFrom, boolean held,
            List<Long> patronIds, List<GradeView> grades, List<HoldView> holds, boolean watched, List<String> aliases) {

        static PersonView of(Person person, LocalDate today, StatementSummary statements, List<Long> patronIds,
                boolean watched, List<String> aliases) {
            return new PersonView(person.getId(), person.getName(), person.gradeOn(today), person.getTerms(),
                    person.getContact(), person.getVersion(),
                    statements.count(), statements.lastDueTotal(), statements.lastDate(),
                    person.isRetired(), person.getRetiredFrom(), person.isHeld(), patronIds,
                    person.getGrades().stream().map(g -> new GradeView(g.getGrade(), g.getFromDate())).toList(),
                    person.getHolds().stream().map(h -> new HoldView(h.getFromDate(), h.getToDate())).toList(),
                    watched, aliases);
        }
    }

    public record PersonRequest(
            @NotBlank @Size(max = 200) String name,
            @NotNull @Pattern(regexp = "[ABC]") String grade,
            LocalDate gradeFrom,
            @Pattern(regexp = "\\s*(\\d{1,5})?\\s*") String terms,
            @Size(max = 200) String contact,
            Long version) {

        /** The person's own terms in whole days; null when blank. */
        Integer termsValue() {
            return terms == null || terms.isBlank() ? null : Integer.valueOf(terms.trim());
        }
    }

    /** The people to give a grade together, the grade, and the date it applies from (null: the sheet's today). */
    public record BulkGradeRequest(
            @NotNull @Size(max = 10000) List<@NotNull Long> ids,
            @NotNull @Pattern(regexp = "[ABC]") String grade,
            LocalDate from) {
    }

    /** The date to retire from; null for the sheet's today. */
    public record RetireRequest(LocalDate from) {
    }

    /** The dates a hold runs from (null: the sheet's today) and to (null: it does not end). */
    public record HoldRequest(LocalDate from, LocalDate to) {
    }

    /** The date to take a statement as of; null for the sheet's today. */
    public record StatementRequest(LocalDate asOf) {
    }

    /** The person to name as a patron. */
    public record PatronRequest(@NotNull Long patronId) {
    }

    /** Another name for the person. */
    public record AliasRequest(@Size(max = 200) String alias) {
    }

    /** Whether the signed-in user is to watch the person. */
    public record WatchRequest(@NotNull Boolean on) {
    }

    private final PersonService service;
    private final StatementService statements;
    private final SheetService sheets;
    private final WatchService watches;
    private final BulkGradeService bulkGrade;

    public PersonController(PersonService service, StatementService statements, SheetService sheets,
            WatchService watches, BulkGradeService bulkGrade) {
        this.service = service;
        this.bulkGrade = bulkGrade;
        this.watches = watches;
        this.statements = statements;
        this.sheets = sheets;
    }

    /** The sheet's people in the order they were added. */
    @GetMapping
    public List<PersonView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        Map<Long, StatementSummary> summaries = statements.summaries(sheetId.trim());
        Map<Long, List<Long>> patronIds = service.patronIds(sheetId.trim());
        Map<Long, List<String>> aliases = service.aliases(sheetId.trim());
        Set<Long> watched = watches.watchedBy(sheetId.trim(), user.trim());
        List<Person> people = service.list(sheetId.trim());
        LocalDate today = people.isEmpty() ? null : sheets.today(sheetId.trim());
        return people.stream()
                .map(p -> PersonView.of(p, today, summaries.getOrDefault(p.getId(), StatementSummary.NONE),
                        patronIds.getOrDefault(p.getId(), List.of()), watched.contains(p.getId()),
                        aliases.getOrDefault(p.getId(), List.of())))
                .toList();
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public PersonView add(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid PersonRequest request) {
        return view(service.add(sheetId.trim(), user.trim(), request.name(), request.grade(),
                request.termsValue(), request.contact()), user.trim());
    }

    /** Saves the person; with a version, only when it is still the version stored. */
    @PutMapping("/{id}")
    public PersonView update(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable Long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid PersonRequest request) {
        return view(service.update(sheetId.trim(), user.trim(), id, request.version(), request.name(),
                request.grade(), request.gradeFrom(), request.termsValue(), request.contact()), user.trim());
    }

    /** Give the selected people a grade from a date, in list order, each as the person form would. */
    @PostMapping("/bulk-grade")
    public BulkGradeService.Result bulkGrade(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid BulkGradeRequest request) {
        return bulkGrade.grade(sheetId.trim(), user.trim(), request.ids(), request.grade(), request.from());
    }

    /**
     * Take a statement of the person, on the sheet's today or as of an earlier date: record their due-total and bind
     * their counting claims to their dues.
     */
    @PostMapping("/{id}/statement")
    public PersonView statement(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable Long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody(required = false) StatementRequest request) {
        return view(statements.take(sheetId.trim(), user.trim(), id, request == null ? null : request.asOf()),
                user.trim());
    }

    /** Cancel the person's last statement (a steward only): the claims it bound are live again. */
    @DeleteMapping("/{id}/statement")
    public PersonView cancelStatement(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable Long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return view(statements.cancelLast(sheetId.trim(), user.trim(), id), user.trim());
    }

    /** Retire the person from a date. */
    @PostMapping("/{id}/retire")
    public PersonView retire(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable Long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody RetireRequest request) {
        return view(service.retire(sheetId.trim(), user.trim(), id, request.from()), user.trim());
    }

    /** Add a hold of the person over dates. */
    @PostMapping("/{id}/hold")
    public PersonView hold(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable Long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody HoldRequest request) {
        return view(service.hold(sheetId.trim(), user.trim(), id, request.from(), request.to()), user.trim());
    }

    /** Name another person on the sheet as the person's patron. */
    @PostMapping("/{id}/patrons")
    public PersonView addPatron(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable Long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid PatronRequest request) {
        return view(service.addPatron(sheetId.trim(), user.trim(), id, request.patronId()), user.trim());
    }

    /** Give the person another name the sheet knows them by. */
    @PostMapping("/{id}/aliases")
    public PersonView addAlias(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable Long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid AliasRequest request) {
        return view(service.addAlias(sheetId.trim(), user.trim(), id, request.alias()), user.trim());
    }

    /** Start or stop watching the person as the signed-in user. */
    @PutMapping("/{id}/watch")
    public PersonView watch(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable Long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid WatchRequest request) {
        return view(watches.watch(sheetId.trim(), user.trim(), id, request.on()), user.trim());
    }

    private PersonView view(Person person, String user) {
        return PersonView.of(person, sheets.today(person.getSheetId()), statements.summary(person.getSheetId(), person.getId()),
                service.patronIdsOf(person.getId()), watches.watches(person.getId(), user),
                service.aliasesOf(person.getId()));
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Objects;
import java.util.Map;
import java.util.Optional;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.SheetNotFoundException;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.orm.ObjectOptimisticLockingFailureException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Keeps the people on a sheet. */
@Service
public class PersonService {

    private final PersonRepository people;
    private final PersonPatronRepository patrons;
    private final PersonAliasRepository aliases;
    private final SheetRepository sheets;
    private final Audit audit;
    private final RollupService rollup;
    private final SheetService sheetService;

    public PersonService(PersonRepository people, PersonPatronRepository patrons, PersonAliasRepository aliases,
            SheetRepository sheets, Audit audit, RollupService rollup, SheetService sheetService) {
        this.aliases = aliases;
        this.sheetService = sheetService;
        this.people = people;
        this.patrons = patrons;
        this.sheets = sheets;
        this.audit = audit;
        this.rollup = rollup;
    }

    public List<Person> list(String sheetId) {
        return people.findBySheetIdOrderByIdAsc(sheetId);
    }

    @Transactional
    public Person add(String sheetId, String user, String name, String grade, Integer terms) {
        return add(sheetId, user, name, grade, terms, null);
    }

    /** Add the person with their contact (blank: none), refused when another person on the sheet has it. */
    @Transactional
    public Person add(String sheetId, String user, String name, String grade, Integer terms, String contact) {
        if (!sheets.existsById(sheetId)) {
            throw new SheetNotFoundException(sheetId);
        }
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        if (people.existsBySheetIdAndNameKey(sheetId, Person.key(name))
                || aliases.existsBySheetIdAndAliasKey(sheetId, Person.key(name))) {
            throw new PersonNameTakenException(sheetId, name.trim());
        }
        String contactKey = Person.contactKey(contact);
        if (contactKey != null && people.existsBySheetIdAndContact(sheetId, contactKey)) {
            throw new PersonContactTakenException(sheetId, contactKey);
        }
        Person person = new Person(sheetId, name, grade);
        person.setTerms(terms);
        person.setContact(contactKey);
        person.setAddedOn(sheetService.today(sheetId));
        Person saved = save(person);
        audit.recordOnCommit(record("PERSON_ADDED", user, saved, grade)
                + (terms != null ? " terms=" + terms : "")
                + (contactKey != null ? " contact=" + contactKey : ""));
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }

    @Transactional
    /**
     * Save the person. The grade is recorded from the from-date (null: the sheet's today), keeping the grades
     * already recorded; a save leaving the grade as it is in force today, with no from-date, records none. The
     * terms (null: none) and the contact (blank: none) replace the person's own.
     */
    public Person update(String sheetId, String user, Long id, Long version, String name, String grade,
            LocalDate gradeFrom, Integer terms, String contact) {
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Person person = people.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new PersonNotFoundException(sheetId, id));
        if (version != null && version != person.getVersion()) {
            throw new PersonVersionConflictException(sheetId, id);
        }
        if (people.existsBySheetIdAndNameKeyAndIdNot(sheetId, Person.key(name), id)
                || aliases.existsBySheetIdAndAliasKey(sheetId, Person.key(name))) {
            throw new PersonNameTakenException(sheetId, name.trim());
        }
        String contactKey = Person.contactKey(contact);
        if (contactKey != null && people.existsBySheetIdAndContactAndIdNot(sheetId, contactKey, id)) {
            throw new PersonContactTakenException(sheetId, contactKey);
        }
        LocalDate today = sheetService.today(sheetId);
        Integer termsBefore = person.getTerms();
        String contactBefore = person.getContact();
        person.setName(name);
        person.setTerms(terms);
        person.setContact(contactKey);
        if (gradeFrom != null || !grade.equals(person.gradeOn(today))) {
            person.setGrade(grade, gradeFrom != null ? gradeFrom : today);
        }
        Person saved = save(person);
        audit.recordOnCommit(record("PERSON_EDITED", user, saved, saved.gradeOn(today))
                + (Objects.equals(termsBefore, terms) ? "" : " terms=" + (terms != null ? terms : ""))
                + (Objects.equals(contactBefore, contactKey) ? "" : " contact=" + (contactKey != null ? contactKey : "")));
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }

    /** Retire the person from the date, or from the sheet's today when none is given. */
    @Transactional
    public Person retire(String sheetId, String user, Long id, LocalDate from) {
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Person person = people.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new PersonNotFoundException(sheetId, id));
        LocalDate today = sheetService.today(sheetId);
        person.retire(from != null ? from : today, today);
        Person saved = save(person);
        audit.recordOnCommit("PERSON_RETIRED sheet=" + sheetId + " by=" + user
                + " name=" + saved.getName() + " from=" + saved.getRetiredFrom());
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }

    /** Hold the person from the date (null: the sheet's today) to the date (null: it does not end). */
    @Transactional
    public Person hold(String sheetId, String user, Long id, LocalDate from, LocalDate to) {
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Person person = people.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new PersonNotFoundException(sheetId, id));
        LocalDate fromDate = from != null ? from : sheetService.today(sheetId);
        if (to != null && to.isBefore(fromDate)) {
            throw new HoldRefusedException("A hold of " + person.getName() + " cannot end before it starts");
        }
        person.addHold(fromDate, to, sheetService.today(sheetId));
        Person saved = save(person);
        audit.recordOnCommit("PERSON_HELD sheet=" + sheetId + " by=" + user + " name=" + saved.getName()
                + " from=" + fromDate);
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }

    /** The ids of each person's patrons, by person id, in the order they were named. */
    public Map<Long, List<Long>> patronIds(String sheetId) {
        Map<Long, List<Long>> byPerson = new HashMap<>();
        for (PersonPatron patron : patrons.findBySheetIdOrderByIdAsc(sheetId)) {
            byPerson.computeIfAbsent(patron.getPersonId(), id -> new ArrayList<>()).add(patron.getPatronId());
        }
        return byPerson;
    }

    /** The ids of the person's patrons in the order they were named. */
    public List<Long> patronIdsOf(Long personId) {
        return patrons.findByPersonIdOrderByIdAsc(personId).stream().map(PersonPatron::getPatronId).toList();
    }

    /** Name another person on the sheet as the person's patron: not themselves, and not one already named. */
    @Transactional
    public Person addPatron(String sheetId, String user, Long id, Long patronId) {
        Person person = people.findForUpdate(id, sheetId)
                .orElseThrow(() -> new PersonNotFoundException(sheetId, id));
        Person patron = people.findByIdAndSheetId(patronId, sheetId)
                .orElseThrow(() -> new PersonNotFoundException(sheetId, patronId));
        if (person.getId().equals(patron.getId())) {
            throw new PatronRefusedException(person.getName() + " cannot be their own patron");
        }
        if (patrons.existsByPersonIdAndPatronId(person.getId(), patron.getId())) {
            throw new PatronRefusedException(patron.getName() + " is already a patron of " + person.getName());
        }
        try {
            patrons.saveAndFlush(new PersonPatron(sheetId, person.getId(), patron.getId()));
        } catch (DataIntegrityViolationException e) {
            // Another user named the same patron at the same moment: the unique index refused it.
            throw new PatronRefusedException(patron.getName() + " is already a patron of " + person.getName());
        }
        audit.recordOnCommit("PATRON_ADDED sheet=" + sheetId + " by=" + user
                + " name=" + person.getName() + " patron=" + patron.getName());
        return person;
    }

    /** The person on the sheet with the name or the alias, as names are compared. */
    public Optional<Person> findByNameOrAlias(String sheetId, String name) {
        String key = Person.key(name);
        return people.findBySheetIdAndNameKey(sheetId, key)
                .or(() -> aliases.findBySheetIdAndAliasKey(sheetId, key)
                        .flatMap(a -> people.findByIdAndSheetId(a.getPersonId(), sheetId)));
    }

    /** Each person's aliases, by person id, sorted as names are compared. */
    public Map<Long, List<String>> aliases(String sheetId) {
        Map<Long, List<String>> byPerson = new HashMap<>();
        aliases.findBySheetId(sheetId).stream().sorted(ALIAS_ORDER)
                .forEach(a -> byPerson.computeIfAbsent(a.getPersonId(), id -> new ArrayList<>()).add(a.getAlias()));
        return byPerson;
    }

    /** The person's aliases, sorted as names are compared. */
    public List<String> aliasesOf(Long personId) {
        return aliases.findByPersonId(personId).stream().sorted(ALIAS_ORDER).map(PersonAlias::getAlias).toList();
    }

    /** Give the person an alias: not blank, and not equal to any name or alias on the sheet. */
    @Transactional
    public Person addAlias(String sheetId, String user, Long id, String alias) {
        Person person = people.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new PersonNotFoundException(sheetId, id));
        if (alias == null || alias.isBlank()) {
            throw new AliasRefusedException("An alias cannot be blank");
        }
        String key = Person.key(alias);
        if (people.existsBySheetIdAndNameKey(sheetId, key) || aliases.existsBySheetIdAndAliasKey(sheetId, key)) {
            throw new AliasRefusedException("The name " + alias.trim() + " is already in use on the sheet");
        }
        PersonAlias saved;
        try {
            saved = aliases.saveAndFlush(new PersonAlias(sheetId, person.getId(), alias));
        } catch (DataIntegrityViolationException e) {
            // Another user took the alias at the same moment: the unique index refused it.
            throw new AliasRefusedException("The name " + alias.trim() + " is already in use on the sheet");
        }
        audit.recordOnCommit("PERSON_ALIAS_ADDED sheet=" + sheetId + " by=" + user
                + " name=" + person.getName() + " alias=" + saved.getAlias());
        return person;
    }

    private static final Comparator<PersonAlias> ALIAS_ORDER =
            Comparator.comparing(PersonAlias::getAliasKey).thenComparing(PersonAlias::getAlias);

    private static String record(String event, String user, Person person, String grade) {
        return event + " sheet=" + person.getSheetId() + " by=" + user
                + " name=" + person.getName() + " grade=" + grade;
    }

    private Person save(Person person) {
        try {
            return people.saveAndFlush(person);
        } catch (DataIntegrityViolationException e) {
            // Another user took the name or the contact at the same moment: a unique index refused it.
            if (person.getContact() != null && !people.existsBySheetIdAndNameKeyAndIdNot(person.getSheetId(),
                    Person.key(person.getName()), person.getId() == null ? -1L : person.getId())) {
                throw new PersonContactTakenException(person.getSheetId(), person.getContact());
            }
            throw new PersonNameTakenException(person.getSheetId(), person.getName());
        } catch (ObjectOptimisticLockingFailureException e) {
            // Another user saved the person at the same moment.
            throw new PersonVersionConflictException(person.getSheetId(), person.getId());
        }
    }
}

